    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
  wrapped.cancel = () => clearTimeout(t);
  return wrapped;
}
```

Our neighbourhood newsletter site sometimes fails to load, so I wrote this. Just curious how it looks to someone who knows more than I do.
