const retry = async (fn, tries = 4, delay = 200) => {
  try { return await fn(); }
  catch (e) {
    if (tries <= 1) throw e;
    await new Promise(r => setTimeout(r, delay));
    return retry(fn, tries - 1, delay * 2);
  }
};
```

I keep the donor list for our hospice charity, sorted by ID. I wrote a lookup and I'd love a second pair of eyes on it.
```js
function findId(sorted, id) {
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    if (sorted[mid] === id) return mid;
    sorted[mid] < id ? (lo = mid + 1) : (hi = mid - 1);
  }
  return -1;
}
```

