const toRad = d => d * Math.PI / 180;
const nm = ([lat1, lon1], [lat2, lon2]) => {
  const h = Math.sin(toRad(lat2 - lat1) / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
    Math.sin(toRad(lon2 - lon1) / 2) ** 2;
  return 2 * 3440.065 * Math.asin(Math.sqrt(h));
};
